"use client"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { PLANS, type OnboardingStepProps } from "../schema"
import { actionsStyle, helpStyle, stepStyle, titleStyle } from "../styles"

export function Done({ data, back, goTo }: OnboardingStepProps) {
  const plan = PLANS.find((p) => p.value === data.plan)?.label
  const firstName = data.fullName.split(" ")[0]
  return (
    <div style={stepStyle}>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
        <h2 style={titleStyle}>You&apos;re all set, {firstName}</h2>
        <p style={helpStyle}>
          {data.skippedPreferences
            ? "We used the default preferences. You can change them in settings."
            : `You're on the ${plan} plan. You can change your preferences in settings.`}
        </p>
      </div>
      <div style={actionsStyle}>
        <Button variant="primary" size="lg" onClick={() => goTo(0)}>Continue to app</Button>
        <div>
          <Button variant="ghost" size="md" onClick={back}>Back</Button>
        </div>
      </div>
    </div>
  )
}
