"use client"
import { FlowShell } from "../_shared/FlowShell"
import { useFlowState } from "../_shared/useFlowState"
import { ONBOARDING_INITIAL, ONBOARDING_STEPS, type OnboardingData } from "./schema"
import { Profile } from "./steps/Profile"
import { Preferences } from "./steps/Preferences"
import { Done } from "./steps/Done"

export default function OnboardingFlowPage() {
  const flow = useFlowState<OnboardingData>({ totalSteps: ONBOARDING_STEPS.length, initialData: ONBOARDING_INITIAL })
  const props = { data: flow.data, patch: flow.patch, next: flow.next, back: flow.back, goTo: flow.goTo }
  const key = ONBOARDING_STEPS[flow.step]
  return (
    <FlowShell
      title="Onboarding"
      step={flow.step}
      totalSteps={ONBOARDING_STEPS.length}
      onReset={flow.reset}
      phoneBackground="var(--atlas-background)"
    >
      {key === "profile" && <Profile {...props} />}
      {key === "preferences" && <Preferences {...props} />}
      {key === "done" && <Done {...props} />}
    </FlowShell>
  )
}
